export const INFO = {"about": {"t": "What is ZIRO?", "tag": "About ZIRO", "intro": "ZIRO is a local marketplace for the GTA where neighbours buy, sell and rent everyday items instead of buying everything new.", "sections": [["Where ZIRO works", "Listings come from sellers in Toronto, Mississauga, Scarborough, Vaughan, Brampton, Etobicoke, Hamilton, Markham, Oakville and Richmond Hill. Every card shows its city, so you can pick things up nearby."], ["Three ways to use ZIRO", "Rent it by the day with Rent It, or post a SNAP IT wanted request when the thing you need is not listed yet."]], "bullets": ["List in minutes with a photo, price and pickup spot.", "Rent It lets you rent instead of buying — daily rates with a refundable deposit.", "SNAP IT posts a wanted request when you can’t find what you need."], "action": ["Browse all listings", "all"]}, "howBuying": {"t": "How buying works", "tag": "Buy · Step by step", "intro": "Buying on ZIRO is three steps: find it, check it, then meet the seller and pay in person.", "sections": [["Step 1 — Find it", "Browse the categories on the home page, or open Gift them home, Cook with heart, Game like a gamer and Move like an athlete for curated picks. Tap the heart on anything you like to keep it in Saved items."], ["Step 2 — Check it", "On the listing page, read the condition, the seller’s returns policy and the reviews other buyers left. Tap Watch for price drop and ZIRO will notify you if the seller lowers the price."], ["Step 3 — Meet and pay", "Message the seller in Chat or tap Make Offer, agree a public place to meet, check the item in person, and only then pay."]], "bullets": ["Tap the heart to save an item to your Saved list.", "Watch a listing to get a price-drop notification.", "Pay with a saved card: add one under Payment methods in the footer, then use it at the Rent It checkout on the listing page and get a payment confirmation.", "Always check the item before you pay."], "action": ["Start browsing listings", "all"]}, "howRenting": {"t": "Renting help — how Rent It works", "tag": "Help & Contact · Renting", "intro": "Every listing on ZIRO can be rented by the day instead of bought. The Rent It panel on each listing page does the maths for you.", "sections": [["Daily rates", "The daily rate is about 4% of the buy price, with a $2 minimum, and it is shown on every card as “Rent it · $X/day”. On the listing page you pick 1, 3, 7, 14 or 30 days and see the total before you confirm."], ["The refundable deposit", "Rentals add a refundable deposit of half the buy price. You get it back when you return the item in the same condition you picked it up in."], ["Pickup and return", "Message the seller in Chat to arrange pickup and return times. Check the item together at pickup so you both agree on its condition."]], "bullets": ["Pick 1, 3, 7, 14 or 30 days on the listing page.", "Deposit is half the buy price and comes back on return.", "Arrange pickup and return with the seller in Chat."], "action": ["Browse rentals", "rent"]}, "startSelling": {"t": "Seller tips", "tag": "Sell · Tips that work", "intro": "Listings with clear photos, honest descriptions and fair prices sell first. Here is what good ZIRO sellers do.", "sections": [["Photos that sell", "Take your own photo in good light — or use SNAP-style photos that show the real item, not a stock picture. Show any wear honestly; buyers trust listings that do."], ["Price it right", "Check what similar items are listed for on ZIRO and price close to that. You can lower your price later from your listing page — anyone watching it gets a price-drop notification, which often brings buyers back."], ["ZIRO takes 10% — price it in", "ZIRO takes 10% from every sale. That means if your item sells for $100, ZIRO keeps $10 and you keep $90. To cover the fee, price your item 10% higher than the amount you actually want to keep — for example, if you want to keep $100, list it for about $110, so after the 10% fee you still get the amount you wanted."], ["Answer fast, meet on time", "Reply to Chat messages quickly and show up when you agreed. Good reviews on your listings come from exactly this."]], "bullets": ["Use a clear title with the brand and size or model.", "Be honest about condition — pick New, Like New or Used truthfully.", "Lower the price from the listing page to trigger price-drop alerts.", "Price 10% higher than what you want to keep — ZIRO takes 10% from every sale."], "action": ["Open the sell form", "sell"]}, "safety": {"t": "Safety tips", "tag": "Help & Contact · Safety", "intro": "Most ZIRO meetups are neighbours swapping everyday items. These habits keep every buy, sale and rental safe — read them before your first meetup.", "sections": [["Meet in a public place", "Always meet in a public, well-lit place in daylight — a coffee shop, library, community centre or mall entrance — never at your home or theirs. Pick somewhere with other people around, and tell someone where you are going and when you expect to be back."], ["Bring an adult", "If you are young, always bring a parent or another trusted adult with you — no exceptions, even for a small item. Grown-ups: bringing a friend along is still a good idea, and it makes checking and carrying bigger items easier too."], ["Never share passwords or bank details", "Never share your password, bank login, card PIN, verification codes or home address with anyone — in Chat or anywhere else. ZIRO will never ask you for them, and a real buyer or seller never needs them. If someone asks, it is a scam: stop replying and report the listing."], ["Check the item before you pay", "Look the item over in person before any money changes hands. Make sure it matches the listing photos and description, and for electronics, turn it on and test it. Only pay once you are holding the item and happy with it."], ["Watch for scams", "Be careful with prices that look too good to be true, anyone pressuring you to pay fast, requests to pay with gift cards or a wire transfer, and links that ask you to sign in again. Keep the conversation inside ZIRO Chat so there is a record of what was agreed."], ["If something feels wrong", "You can always walk away — no deal is worth feeling unsafe. Stop replying, don’t meet up, and use the Report button on the listing page so ZIRO knows. For rentals, agree the return time and the item’s condition in Chat before pickup, and check the item together at handover."]], "bullets": ["Meet in public, in daylight, with people around.", "Young users: always bring a parent or trusted adult.", "Never share passwords, bank details, PINs or codes — ZIRO never asks for them.", "Check the item in person before you pay.", "Keep chat inside ZIRO and report anything that feels wrong."], "action": ["Read the community guidelines", "info:guidelines"]}, "returns": {"t": "Returns & refunds", "tag": "Help & Contact · Returns", "intro": "There is no single ZIRO returns policy — each seller sets their own, and it is printed on every listing under Returns.", "sections": [["Check the listing first", "Before you buy, look at the Returns line on the listing page. Many sellers accept returns within 7 days if the item is not as described; others list “No returns”, so ask in Chat first if it matters to you."], ["If something isn’t right", "Message the seller first — most problems are a misunderstanding and get sorted in Chat. Explain what is different from the listing and agree together what happens next."], ["Rental deposits", "For Rent It rentals, the refundable deposit comes back when the item is returned in the same condition. Damage or a missing item is the one reason a seller can keep some or all of it — which is why checking the item together at pickup matters."]], "bullets": ["The seller’s returns policy is shown on every listing.", "Message the seller first if an item is not as described.", "Rental deposits are refunded on a same-condition return."], "action": ["Browse listings and check their policies", "all"]}, "contact": {"t": "Contact & help centre", "tag": "Help & Contact", "intro": "Almost every question on ZIRO is about one specific item — and the fastest help always comes from that item’s seller.", "sections": [["Help with an item", "Open the listing and tap Message Seller. The seller knows the item’s condition, pickup spot and returns policy better than anyone, and they reply fastest."], ["Help with your own listing", "Your listings page lists everything you created with SELL. Open a listing there to change its price — watchers are notified automatically when you drop it."], ["Help with safety", "If a conversation feels wrong, stop replying and don’t meet up. The Safety tips page covers what to watch for, and the Guidelines page covers what is not allowed on ZIRO."]], "bullets": ["For an item: message its seller from the listing page.", "For your listings: open Your listings under Sell in the footer.", "For safety: read Safety tips before any meetup."], "action": ["Chat with a seller", "chat"]}, "community": {"t": "Community life on ZIRO", "tag": "Community", "intro": "ZIRO works because neighbours treat it like a neighbourhood: good stuff gets reused instead of thrown away, and people show up for each other.", "sections": [["Neighbours first", "Sellers are people a few streets or one city over — Toronto to Richmond Hill. Kind messages, honest listings and on-time meetups are the whole culture."], ["Reviews make it work", "After a meetup, the reviews on a listing page tell the next buyer what a seller is like. Fair reviews help good sellers stand out and keep standards high for everyone."], ["Curated collections", "Gift them home, Cook with heart, Game like a gamer and Move like an athlete are collections built from real local listings — a good place to see what the community is listing right now."]], "bullets": ["Be kind in Chat and describe items honestly.", "Leave a fair review after a meetup.", "Local deals near you collects the cheapest listings across the GTA."], "action": ["See local deals near you", "local"]}, "guidelines": {"t": "Community guidelines", "tag": "Community · The rules", "intro": "A few simple rules keep ZIRO honest and useful. Listings or behaviour that break them don’t belong here.", "sections": [["List only what’s real", "Only list items you actually have and are allowed to sell or rent, with your own photos and a real price. No misleading photos, fake prices or spam listings."], ["Describe it truthfully", "Pick the condition honestly — New, Like New or Used — and mention wear, faults or missing parts in the description."], ["Respect people’s time", "Reply to messages, keep agreed pickup times, and be polite in Chat even when a deal doesn’t happen."]], "bullets": ["No fake prices, stock-photo listings or spam.", "No sharing other people’s private information.", "Meet safely — the Safety tips page explains how."], "action": ["Read the safety tips", "info:safety"]}, "rentOut": {"t": "Rent out your items", "tag": "Sell · Rent out", "intro": "Don’t just sell it — rent it out. Every listing on ZIRO automatically gets a Rent It daily rate, so things sitting in your garage or closet can earn while a neighbour uses them.", "sections": [["How it works", "List your item with SELL as usual. Renters see the daily rate (about 4% of the buy price, $2 minimum) on the card, pick 1, 3, 7, 14 or 30 days on your listing page, and see the total plus the refundable deposit — half the buy price — before they rent."], ["What rents well", "Things neighbours need once in a while rent best: tools, sports gear, party items, electronics, games and kitchen gear for big cooking days."], ["Handing it over", "Arrange pickup in Chat, check the item’s condition together, and the deposit goes back to the renter when it comes back the same way."]], "bullets": ["No separate rental listing needed — every listing can be rented.", "You set the buy price; the daily rate and deposit follow from it.", "Agree pickup and return in Chat."], "action": ["List something to rent out", "sell"]}, "sellerReviews": {"t": "Seller reviews", "tag": "Community · Reviews", "intro": "Every seller on ZIRO can be reviewed by the people who bought or rented from them. Reviews are how buyers decide who to trust.", "sections": [["Where reviews live", "Open any listing: the seller’s average star rating and review count sit under their name, and the Seller Reviews section on the same page shows what each reviewer actually said."], ["What makes a good review", "Reviews mention whether the item matched its description, whether the seller replied quickly, and whether they showed up on time — the three things the next buyer cares about."], ["Earning great reviews", "Honest descriptions, clear photos, fast replies and on-time meetups. There is no shortcut — sellers with strong reviews sell and rent faster."]], "bullets": ["Star ratings show on every listing page.", "Read the full reviews in the Seller Reviews section of a listing.", "Message a seller from their listing with any questions first."], "action": ["Browse listings and check a seller", "all"]}, "terms": {"t": "Terms of Service", "tag": "Help & Contact · The rules for using ZIRO", "intro": "These are the rules for using ZIRO, written in plain language. By using ZIRO, you agree to them.", "sections": [["What ZIRO is", "ZIRO is a local marketplace for the GTA where people buy, sell and rent used items. ZIRO runs the marketplace — the items themselves are listed and sold by individual sellers, not by ZIRO."], ["Your listings", "Only list items you own and are allowed to sell or rent. Use your own photos, describe the item honestly (including its condition), and set a real price. No fake listings, no spam, and nothing illegal, stolen or dangerous — the Community guidelines page lists what is not allowed."], ["The 10% fee on sales", "ZIRO takes 10% from every sale. If an item sells for $100, ZIRO keeps $10 and the seller keeps $90. Sellers can price with the fee in mind — Seller tips explains how to price 10% higher so the fee is covered."], ["Ads", "An image ad costs $0.99 and a video ad costs $2.99. A submitted ad stays pending and hidden until it is paid for; once paid it goes live only on the home page banner. Clicks on ads and listings are counted, and the most-clicked ads show first."], ["Rent It", "Any listing can be rented for 1, 3, 7, 14 or 30 days at the daily rate shown on the listing, plus a refundable deposit of half the buy price. The deposit comes back when the item is returned on time and in the same condition it was picked up in."], ["Payments", "You can save a card on the Payment methods page and use it to pay for ads and rentals. ZIRO stores only the card’s brand, last 4 digits and expiry — never the full card number or CVC."], ["Returns", "Each seller sets their own returns policy, and it is shown on every listing. Check it before you buy. If an item is not as described, message the seller first — the Returns & refunds page explains how it works."], ["Reporting and safety", "Use the Report button on any listing that looks wrong, fake or unsafe. Follow the Safety tips: meet in a public place, bring an adult, never share passwords or bank details, and check items before you pay. Listings and ads that break these terms can be removed."], ["Changes to these terms", "These terms may be updated as ZIRO grows. The version on this page is always the current one."]], "bullets": ["Only list items you own, with honest photos and prices.", "ZIRO takes 10% of every sale — the seller keeps 90%.", "Ads cost $0.99 (image) or $2.99 (video) and go live only after payment, only on the home page banner.", "Meet safely, and check the item before you pay."], "action": ["Read the privacy policy", "info:privacy"]}, "privacy": {"t": "Privacy Policy", "tag": "Help & Contact · Your information", "intro": "This page explains, in plain language, what information ZIRO keeps and what it does with it.", "sections": [["What ZIRO collects", "ZIRO keeps the things you create while using it: listings (photos, title, price, description and city), items you save or watch, messages you send in Chat, SNAP IT wanted requests, reports you file, ads you submit, and a record of payments you make."], ["Your card details", "When you add a card on the Payment methods page, ZIRO stores only the card brand, the last 4 digits and the expiry date. Your full card number and CVC are checked when you add the card and are never stored."], ["How your information is used", "Your information is used to run the marketplace: showing your listings to buyers, sending you price-drop notifications for listings you watch, showing your ads on the home page banner, counting clicks on listings and ads, and keeping your payment history under Recent payments."], ["What ZIRO never does", "ZIRO never sells your personal information. ZIRO also never asks for your password, bank login or verification codes — if someone asks for those in Chat, it is a scam. Stop replying and report the listing."], ["What other people can see", "Your listings, your store name and the reviews on your listings are public — anyone on ZIRO can see them. Your saved items, watch list, payment methods, notifications and payment history are only visible to you."], ["Removing your information", "You can delete your own listings, ads, saved items and saved cards at any time from their pages. Deleting a listing also removes the chats about it."]], "bullets": ["Only your card’s brand, last 4 digits and expiry are stored — never the full number or CVC.", "Your information runs the marketplace; it is never sold.", "Listings and reviews are public; saves, watches, cards and payments are private to you.", "ZIRO never asks for your password or bank details."], "action": ["Read the terms of service", "info:terms"]}, "launch": {"t": "Launch checklist", "tag": "About ZIRO · For the owner", "intro": "What is already built inside ZIRO, and what still has to happen outside ZIRO before a real public launch. This page is for ZIRO’s owner.", "sections": [["Ready inside ZIRO", "The marketplace itself is built: listings across 10 GTA cities with categories, filters and sort; the Sell form and Your listings; Rent It with daily rates and refundable deposits; Saved items and price-drop notifications; Chat; SNAP IT wanted requests; a Report button on every listing; paid ads ($0.99 image / $2.99 video) that stay pending until paid, show only on the home page banner, and rank most-clicked first; payment methods with an in-app checkout; and the trust pages — Terms of Service, Privacy Policy, Safety tips, Returns & refunds and Community guidelines — all linked in the footer."], ["Still needed: a real home on the internet", "ZIRO currently lives inside Muse as a working demo. A real public launch needs real hosting and a domain name so anyone can visit ZIRO in their own browser, any time, without Muse."], ["Still needed: real payments", "ZIRO’s checkout records payments inside the app, but no real money moves yet. Charging real cards needs a real payment provider such as Stripe — and an adult has to set that account up, because payment providers require an adult with ID and a bank account."], ["Still needed: real users and cleanup", "The listings in ZIRO today are sample listings made for the demo. Before a real launch: remove the test and seed data, invite real sellers to list real items, and have a plan — with an adult’s help — for reading reports, removing bad listings and keeping meetups safe."]], "bullets": ["Done in ZIRO: marketplace, Rent It, ads, checkout, reporting, and the Terms, Privacy and Safety pages.", "Not done yet: public hosting and a domain name.", "Not done yet: real Stripe payments — an adult needs to set that up.", "Not done yet: remove the sample listings and bring in real users."], "action": ["Read the terms of service", "info:terms"]}, "buyHub": {"t": "Buying on ZIRO", "tag": "Buy", "intro": "Everything for buyers lives under Buy in the footer. This page is the map — each link below opens a different page.", "sections": [["Ways to buy", "Browse all listings shows everything for sale across the GTA. Rent It shows the same marketplace as rentals, priced by the day. Best deals sorts the cheapest listings first so bargains are easy to spot."], ["Keep track of favourites", "Saved items is your wishlist — tap the heart on any listing. Price-drop alerts live in Notifications: watch a listing and ZIRO tells you when its price falls."]], "bullets": ["Browse all listings — every item, newest first.", "Rent It — rent by the day instead of buying.", "Best deals — lowest prices first.", "Saved items and price-drop alerts keep your favourites in one place."], "links": [["Browse all listings", "all"], ["Rent It", "rent"], ["Best deals", "best"], ["Saved items", "saved"], ["Recently viewed", "recent"], ["Price-drop alerts", "alerts"], ["How buying works", "info:howBuying"]]}, "sellHub": {"t": "Selling on ZIRO", "tag": "Sell", "intro": "Everything for sellers lives under Sell in the footer. This page is the map — each link below opens a different page.", "sections": [["Get listed", "Start selling opens the sell form: photo, title, price, condition and pickup city, and your listing is live right away. Your listings is where you view or delete what you created."], ["More ways to earn", "SNAP IT shows wanted requests from buyers looking for specific items — if you own one, that’s a ready-made sale. And every listing can also be rented out by the day with Rent It."]], "bullets": ["Start selling — the sell form.", "Your listings — view or delete your listings.", "SNAP IT — buyers’ wanted requests.", "Seller tips and Rent out your items — advice pages under Sell."], "links": [["Start selling", "sell"], ["Your listings", "your"], ["SNAP IT — wanted requests", "snap"], ["Seller tips", "info:startSelling"], ["Rent out your items", "info:rentOut"]]}, "aboutHub": {"t": "Explore ZIRO", "tag": "About ZIRO", "intro": "What ZIRO is, and the collections that show it off. Each link below opens a different page.", "sections": [["The idea", "ZIRO is a GTA marketplace built around reuse: the lamp, skillet or game you no longer need is exactly what a neighbour is looking for. “What is ZIRO?” explains how buying, selling, renting and SNAP IT fit together."], ["The collections", "Gift them home collects home favourites, Cook with heart collects kitchen gear, Game like a gamer collects consoles and games, and Move like an athlete collects sports gear — all from real listings."]], "bullets": ["What is ZIRO? — the marketplace explained.", "Gift them home — lamps, clocks, candles and more.", "Cook with heart — kitchen gear.", "Game like a gamer and Move like an athlete — games and sports.", "Launch checklist — what’s ready in ZIRO and what’s left for a real launch."], "links": [["What is ZIRO?", "info:about"], ["Gift them home", "theme:home"], ["Cook with heart", "theme:kitchen"], ["Game like a gamer", "theme:gamer"], ["Move like an athlete", "theme:sports"], ["Launch checklist", "info:launch"]]}, "helpHub": {"t": "Help centre — all topics", "tag": "Help & Contact", "intro": "Every help topic has its own page. Pick the one that matches your question — each link below opens a different page.", "sections": [["Start with the topic", "Contact & help centre explains who to message for what. Returns & refunds explains seller policies and rental deposits. Safety tips covers meeting up safely, Renting help explains daily rates and deposits, the Terms of Service set out the rules and fees, and the Privacy Policy explains what ZIRO keeps and why."], ["Fastest answer", "For anything about one specific item, its seller is the fastest answer — open the listing and tap Message Seller, or open Chat below."]], "bullets": ["Contact & help centre — who to message.", "Returns & refunds — policies and deposits.", "Safety tips — meet up safely.", "Renting help — how Rent It works.", "Terms of Service — the rules, the 10% fee and ad prices.", "Privacy Policy — what ZIRO keeps and why."], "links": [["Contact & help centre", "info:contact"], ["Returns & refunds", "info:returns"], ["Safety tips", "info:safety"], ["Chat with a seller", "chat"], ["Renting help", "info:howRenting"], ["Terms of Service", "info:terms"], ["Privacy Policy", "info:privacy"]]}, "communityHub": {"t": "Our community", "tag": "Community", "intro": "The community pages explain how ZIRO neighbours buy, sell and rent well together. Each link below opens a different page.", "sections": [["How we treat each other", "Community life on ZIRO is about the culture — kind chat, honest listings, fair reviews. The Guidelines page is the rulebook version of the same idea."], ["Trust signals", "Seller reviews shows how star ratings and reviews on listing pages help you pick who to buy or rent from. Local deals near you is the community’s cheapest listings, nearest first."]], "bullets": ["Community life on ZIRO — the culture.", "Guidelines — the rules.", "Seller reviews — ratings explained.", "Local deals near you — cheap and close."], "links": [["Community life on ZIRO", "info:community"], ["Guidelines", "info:guidelines"], ["Seller reviews", "info:sellerReviews"], ["Local deals near you", "local"]]}}

